sp_FiltrarProduto	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_FiltrarProduto`(\n\n    IN p_idEmpresa     INT,\n\n    IN p_nome          VARCHAR(100),\n\n    IN p_codProduto    VARCHAR(15),\n\n    IN p_codBarras     VARCHAR(14),\n\n    IN p_idCategoria   INT,\n\n    IN p_idUnidade     INT,\n\n    IN p_fAtivo        TINYINT,\n\n    IN p_precoVendaMin DECIMAL(10,2),\n\n    IN p_precoVendaMax DECIMAL(10,2),\n\n    IN p_estoqueBaixo  TINYINT\n\n)\nBEGIN\n\n    SELECT\n\n        p.idProduto,\n\n        p.idEmpresa,\n\n        p.Nome                      AS nome,\n\n        p.Descricao                 AS descricao,\n\n        p.codProduto                AS sku,\n\n        p.codBarras                 AS codigoBarras,\n\n        p.precoCusto,\n\n        p.precoVenda,\n\n        p.Tributacao                AS tributacao,\n\n        p.categoriaProduto_id       AS idCategoria,\n\n        cp.Nome                     AS nomeCategoria,\n\n        p.uniMedida_id              AS idUnidade,\n\n        um.Sigla                    AS siglaUnidade,\n\n        COALESCE(e.QtdeAtual, 0)    AS qtdEstoque,\n\n        COALESCE(e.estoqueMin, 0)   AS estoqueMin,\n\n        p.fAtivo,\n\n        p.dthCadastro\n\n    FROM Produto p\n\n    LEFT JOIN CategoriaProduto cp ON cp.idCategoriaProduto = p.categoriaProduto_id\n\n    LEFT JOIN UnidadeMedida    um ON um.idUnidade          = p.uniMedida_id\n\n    LEFT JOIN Estoque          e  ON e.produto_id          = p.idProduto\n\n    WHERE p.idEmpresa = p_idEmpresa\n\n      AND (p_nome          IS NULL OR p.Nome       LIKE CONCAT('%', p_nome,      '%'))\n\n      AND (p_codProduto    IS NULL OR p.codProduto LIKE CONCAT('%', p_codProduto,'%'))\n\n      AND (p_codBarras     IS NULL OR p.codBarras  LIKE CONCAT('%', p_codBarras, '%'))\n\n      AND (p_idCategoria   IS NULL OR p.categoriaProduto_id = p_idCategoria)\n\n      AND (p_idUnidade     IS NULL OR p.uniMedida_id        = p_idUnidade)\n\n      AND (p_fAtivo        IS NULL OR p.fAtivo              = p_fAtivo)\n\n      AND (p_precoVendaMin IS NULL OR p.precoVenda >= p_precoVendaMin)\n\n      AND (p_precoVendaMax IS NULL OR p.precoVenda <= p_precoVendaMax)\n\n      AND (p_estoqueBaixo  IS NULL OR p_estoqueBaixo = 0\n\n                                   OR COALESCE(e.QtdeAtual, 0) <= COALESCE(e.estoqueMin, 0))\n\n    ORDER BY p.Nome;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
